using UnityEngine;
public class WoodlandNodeRepair:MonoBehaviour {
 public WoodlandPlayer player;public Transform cover,cartridge,repairArm,rightArm,switchLever;
 public bool Busy{get;private set;}public string Phase{get;private set;}="";public const float Duration=9.5f;
 float elapsed;Vector3 rifleRest,filterRest,filterScale,armRest,rightRest,startPosition;Quaternion cameraRest,armRotation,rightRotation,coverRotation,filterRotation,switchRotation;Vector3 armScale,rightScale;Renderer leftGlove,rightGlove;Transform[] extensions=new Transform[2];
 static float Ease(float t,float a,float b){float u=Mathf.InverseLerp(a,b,t);return u*u*u*(u*(u*6-15)+10);}
 Renderer Glove(Transform arm){foreach(var r in arm.GetComponentsInChildren<Renderer>(true))if(r.name=="Inspection glove")return r;return null;}
 public bool Begin(){if(Busy||player.serviced||!cover||!cartridge||!repairArm||!rightArm||!switchLever)return false;rifleRest=player.rifle.localPosition;filterRest=cartridge.localPosition;filterRotation=cartridge.localRotation;filterScale=cartridge.localScale;armRest=repairArm.localPosition;rightRest=rightArm.localPosition;cameraRest=player.eye.transform.localRotation;armRotation=repairArm.localRotation;rightRotation=rightArm.localRotation;armScale=repairArm.localScale;rightScale=rightArm.localScale;coverRotation=cover.localRotation;switchRotation=switchLever.localRotation;startPosition=player.transform.position;leftGlove=Glove(repairArm);rightGlove=Glove(rightArm);elapsed=0;Busy=true;player.adsRifle.gameObject.SetActive(false);player.focusRifle.gameObject.SetActive(false);player.watch.gameObject.SetActive(false);Sample(0);return true;}
 public void Advance(float dt){if(!Busy)return;elapsed+=Mathf.Max(0,dt);Sample(elapsed);if(elapsed>=Duration){Restore(true);player.CompleteServiceRelay();Phase="Relay connected";}}
 void Hand(Transform arm,Renderer glove,Vector3 contact,float reach,bool right,int index){arm.localScale=(right?rightScale:armScale)*.68f;arm.localPosition=new Vector3(right?.28f:-.28f,-.6f,.32f);arm.localRotation=Quaternion.Euler(15,180,right?-35:35);if(glove)arm.position+=(contact-glove.bounds.center)*reach;arm.gameObject.SetActive(reach>.001f);Renderer sleeve=null;foreach(var r in arm.GetComponentsInChildren<Renderer>(true))if(r.name=="olive sleeve")sleeve=r;if(!sleeve)return;if(!extensions[index]){var g=GameObject.CreatePrimitive(PrimitiveType.Capsule);Destroy(g.GetComponent<Collider>());g.name="Repair sleeve extension";g.GetComponent<Renderer>().sharedMaterial=sleeve.sharedMaterial;extensions[index]=g.transform;}var ext=extensions[index];ext.gameObject.SetActive(arm.gameObject.activeSelf);Vector3 a=sleeve.bounds.center,b=player.eye.transform.TransformPoint(new Vector3(right?.48f:-.48f,-.62f,.1f));ext.position=(a+b)*.5f;ext.rotation=Quaternion.FromToRotation(Vector3.up,a-b);ext.localScale=new Vector3(.14f,Vector3.Distance(a,b)*.5f,.14f);}
 public void Sample(float time){float lower=Ease(time,0,.65f)*(1-Ease(time,8.6f,Duration));player.rifle.localPosition=rifleRest+Vector3.down*.85f*lower;player.rifle.gameObject.SetActive(time<.7f||time>8.7f);Vector3 dock=player.sensor.position-player.sensor.forward*.92f;dock.y=WoodlandCompanion.Ground(dock.x,dock.z)+.04f;var cc=player.GetComponent<CharacterController>();Vector3 pos=Vector3.Lerp(startPosition,dock,Ease(time,0,.8f));if(time<.85f&&cc&&cc.enabled)cc.Move(pos-player.transform.position);Quaternion look=Quaternion.LookRotation(player.sensor.position+Vector3.up*.05f-player.eye.transform.position,Vector3.up);player.eye.transform.localRotation=Quaternion.Slerp(cameraRest,Quaternion.Inverse(player.eye.transform.parent.rotation)*look,lower);
 float open=Ease(time,.9f,1.7f);cover.localRotation=coverRotation*Quaternion.Euler(0,112*open,0);
 float pull=Ease(time,3,4.3f);Vector3 hold=player.eye.transform.TransformPoint(new Vector3(-.14f,-.14f,.50f));Vector3 seated=cartridge.parent.TransformPoint(filterRest);cartridge.position=Vector3.Lerp(seated,hold,pull);cartridge.localRotation=filterRotation*Quaternion.Euler(0,18*Ease(time,2.55f,2.9f)*(1-pull),0);cartridge.gameObject.SetActive(time<8.4f);if(time>7.5f)cartridge.position+=player.eye.transform.up*(-.7f*Ease(time,7.5f,8.4f));
 Vector3 leftContact=Vector3.Lerp(cover.TransformPoint(new Vector3(-.40f,0,-.04f)),cartridge.position+Vector3.up*.09f,Ease(time,1.8f,2.35f));Vector3 rightContact=cartridge.position-Vector3.up*.10f;rightContact=Vector3.Lerp(rightContact,switchLever.position-player.sensor.forward*.035f,Ease(time,4.6f,5.3f));rightContact+=Vector3.up*(.07f*Ease(time,5.6f,5.85f));switchLever.localRotation=switchRotation*Quaternion.Euler(135*Ease(time,5.6f,5.85f),0,0);
 Hand(repairArm,leftGlove,leftContact,Ease(time,.6f,.95f)*(1-Ease(time,7.8f,8.5f)),false,0);Hand(rightArm,rightGlove,rightContact,Ease(time,1.8f,2.4f)*(1-Ease(time,6.3f,7.1f)),true,1);
 Phase=time<.9f?"Reaching relay":time<1.8f?"Opening service cover":time<3?"Unlocking intake filter":time<4.6f?"Withdrawing filter":time<5.6f?"Reaching reset switch":time<6.2f?"Switching relay ON":time<7.5f?"Checking relay connection":"Stowing removed filter";}
 public void Cancel(){if(!Busy)return;Restore(false);Phase="Repair interrupted — E to retry";}
 void Restore(bool complete){Busy=false;foreach(var e in extensions)if(e)e.gameObject.SetActive(false);player.rifle.localPosition=rifleRest;player.rifle.gameObject.SetActive(true);player.eye.transform.localRotation=cameraRest;cartridge.localPosition=filterRest;cartridge.localRotation=filterRotation;cartridge.localScale=filterScale;cartridge.gameObject.SetActive(!complete);cover.localRotation=complete?coverRotation*Quaternion.Euler(0,112,0):coverRotation;switchLever.localRotation=complete?switchRotation*Quaternion.Euler(135,0,0):switchRotation;repairArm.localPosition=armRest;repairArm.localRotation=armRotation;repairArm.localScale=armScale;rightArm.localPosition=rightRest;rightArm.localRotation=rightRotation;rightArm.localScale=rightScale;repairArm.gameObject.SetActive(false);rightArm.gameObject.SetActive(false);}
 void OnDestroy(){foreach(var e in extensions)if(e)Destroy(e.gameObject);}void OnDisable(){if(Busy)Restore(false);}
}
